ARCHAEOLOGY_PROJECTS = {
	[9] = { branch = 1, name = "Пьютеровый кубок", description = "Дворфы Стальгорна некогда происходили из трех кланов: Бронзобородов, Громового Молота и Черного Железа. После гражданской войны Бронзобороды остались править в Стальгорне, клан Громового Молота отступил во Внутренние Земли и на Сумеречное нагорье. Дворфы же Черного Железа обосновались между Красногорьем и Пылающими степями, под сенью Черной горы.", rare = false, fragments = 35, sockets = 1, texture = "Interface\\Archeology\\Arch-Race-DwarfBIG" },
