	[77] = { branch = 8, name = "Зандаларская кукла вуду", description = "Полагают, что племя Зандалар было первым племенем троллей и что все остальные тролли произошли от него. Зандалар считались высшей кастой жрецов. Тролли из этого племени без устали работали над тем, чтобы сохранить традиции троллей и их социальный уклад. Из многочисленных племен, отколовшихся ранее от Зандалар, двумя самыми могущественными являются Гурубаши и Амани.", rare = false, fragments = 27, sockets = 0, texture = "Interface\\Archeology\\Arch-Race-TrollBIG" },
