	[153] = { branch = 8, name = "Горшок для цветов в форме черепа", description = "Полагают, что племя Зандалар было первым племенем троллей и что все остальные тролли произошли от него. Зандалар считались высшей кастой жрецов. Тролли из этого племени без устали работали над тем, чтобы сохранить традиции троллей и их социальный уклад. Из многочисленных племен, отколовшихся ранее от Зандалар, двумя самыми могущественными являются Гурубаши и Амани.", rare = false, fragments = 35, sockets = 1, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[155] = { branch = 8, name = "Браслет из нефрита и монет", description = "Полагают, что племя Зандалар было первым племенем троллей и что все остальные тролли произошли от него. Зандалар считались высшей кастой жрецов. Тролли из этого племени без устали работали над тем, чтобы сохранить традиции троллей и их социальный уклад. Из многочисленных племен, отколовшихся ранее от Зандалар, двумя самыми могущественными являются Гурубаши и Амани.", rare = false, fragments = 35, sockets = 1, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[157] = { branch = 8, name = "Статуэтка Газ'риллы", description = "Полагают, что племя Зандалар было первым племенем троллей и что все остальные тролли произошли от него. Зандалар считались высшей кастой жрецов. Тролли из этого племени без устали работали над тем, чтобы сохранить традиции троллей и их социальный уклад. Из многочисленных племен, отколовшихся ранее от Зандалар, двумя самыми могущественными являются Гурубаши и Амани.", rare = false, fragments = 35, sockets = 1, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[159] = { branch = 8, name = "Скипетр Атал'ай", description = "Полагают, что племя Зандалар было первым племенем троллей и что все остальные тролли произошли от него. Зандалар считались высшей кастой жрецов. Тролли из этого племени без устали работали над тем, чтобы сохранить традиции троллей и их социальный уклад. Из многочисленных племен, отколовшихся ранее от Зандалар, двумя самыми могущественными являются Гурубаши и Амани.", rare = false, fragments = 35, sockets = 1, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[161] = { branch = 3, name = "Зуб дьявозавра", description = "Ископаемые – это сохранившиеся останки животных и растений древних эпох. Как правило, живые ткани замещаются минералами, которые сохраняют строение некогда живого организма.", rare = false, fragments = 35, sockets = 0, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[163] = { branch = 3, name = "Кусочек янтаря с насекомым внутри", description = "Ископаемые – это сохранившиеся останки животных и растений древних эпох. Как правило, живые ткани замещаются минералами, которые сохраняют строение некогда живого организма.", rare = false, fragments = 35, sockets = 0, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[165] = { branch = 4, name = "Калдорайская амфора", description = "Калдорай – одна из древнейших рас Азерота. Самый мрачный момент в их истории пришелся на период, когда кель'дорай – Высокорожденные, высшая каста эльфов – высвободили опасную магию. Она привлекла в мир Пылающий Легион, чей приход повлек за собой бесчисленные жертвы.", rare = false, fragments = 35, sockets = 1, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[167] = { branch = 3, name = "Челюсти древней акулы", description = "Ископаемые – это сохранившиеся останки животных и растений древних эпох. Как правило, живые ткани замещаются минералами, которые сохраняют строение некогда живого организма.", rare = false, fragments = 35, sockets = 0, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[169] = { branch = 4, name = "Серебряная заколка для волос с малахитом", description = "Калдорай – одна из древнейших рас Азерота. Самый мрачный момент в их истории пришелся на период, когда кель'дорай – Высокорожденные, высшая каста эльфов – высвободили опасную магию. Она привлекла в мир Пылающий Легион, чей приход повлек за собой бесчисленные жертвы.", rare = false, fragments = 35, sockets = 1, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[171] = { branch = 4, name = "Изящная музыкальная шкатулка", description = "Калдорай – одна из древнейших рас Азерота. Самый мрачный момент в их истории пришелся на период, когда кель'дорай – Высокорожденные, высшая каста эльфов – высвободили опасную магию. Она привлекла в мир Пылающий Легион, чей приход повлек за собой бесчисленные жертвы.", rare = false, fragments = 35, sockets = 1, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[173] = { branch = 4, name = "Зеркало души Высокорожденных", description = "Хотя стекло разбито на тысячи осколков, филигранный узор на раме зеркала не оставляет сомнений в том, что некогда это был могущественный волшебный артефакт, который после воссоздания вернет себе былую силу. Зеркало довольно большое – такое женщина могла бы держать у себя в гардеробной.", rare = true, fragments = 100, sockets = 3, texture = "Interface\\Archeology\\ArchRare-HighborneSoulMirror" },
	[175] = { branch = 4, name = "Статуэтки женщины-друида и мужчины-жреца", description = "Перед вами обломки двух статуй из драгоценного металла. Они выглядят так, словно их не высекли и не отлили, а вырастили, обойдясь без единого прикосновения мастера. Обе статуи изображают ночных эльфов. Жрец, судя по всему, мужчина, а друид – женщина, что, похоже, неспроста.", rare = true, fragments = 100, sockets = 3, texture = "Interface\\Archeology\\ArchRare-DruidandPriestStatue" },
	[177] = { branch = 1, name = "Пробитый щит Хоруза Вранобоя", description = "Дворфы Стальгорна некогда происходили из трех кланов: Бронзобородов, Громового Молота и Черного Железа. После гражданской войны Бронзобороды остались править в Стальгорне, клан Громового Молота отступил во Внутренние Земли и на Сумеречное нагорье. Дворфы же Черного Железа обосновались между Красногорьем и Пылающими степями, под сенью Черной горы.", rare = false, fragments = 35, sockets = 1, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[179] = { branch = 1, name = "Обугленный посох жреца тени Анунда", description = "Дворфы Стальгорна некогда происходили из трех кланов: Бронзобородов, Громового Молота и Черного Железа. После гражданской войны Бронзобороды остались править в Стальгорне, клан Громового Молота отступил во Внутренние Земли и на Сумеречное нагорье. Дворфы же Черного Железа обосновались между Красногорьем и Пылающими степями, под сенью Черной горы.", rare = false, fragments = 35, sockets = 1, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[181] = { branch = 1, name = "Скипетр Чарлгы Остробок", description = "Дворфы Стальгорна некогда происходили из трех кланов: Бронзобородов, Громового Молота и Черного Железа. После гражданской войны Бронзобороды остались править в Стальгорне, клан Громового Молота отступил во Внутренние Земли и на Сумеречное нагорье. Дворфы же Черного Железа обосновались между Красногорьем и Пылающими степями, под сенью Черной горы.", rare = false, fragments = 35, sockets = 1, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[183] = { branch = 1, name = "Мифриловая цепь Кузни Гнева", description = "Дворфы Стальгорна некогда происходили из трех кланов: Бронзобородов, Громового Молота и Черного Железа. После гражданской войны Бронзобороды остались править в Стальгорне, клан Громового Молота отступил во Внутренние Земли и на Сумеречное нагорье. Дворфы же Черного Железа обосновались между Красногорьем и Пылающими степями, под сенью Черной горы.", rare = false, fragments = 35, sockets = 1, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[185] = { branch = 1, name = "Тенегорнский посох с черепом", description = "Дворфы Стальгорна некогда происходили из трех кланов: Бронзобородов, Громового Молота и Черного Железа. После гражданской войны Бронзобороды остались править в Стальгорне, клан Громового Молота отступил во Внутренние Земли и на Сумеречное нагорье. Дворфы же Черного Железа обосновались между Красногорьем и Пылающими степями, под сенью Черной горы.", rare = false, fragments = 35, sockets = 1, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[187] = { branch = 1, name = "Заводной гном", description = "Вы нашли несколько обломков механического существа, предположительно высокотехнологичного. Возможно, это части механогнома, что встречаются в Нордсколе. Для чего дворфы перенесли эти части сюда, остается загадкой. Вы размышляете, получится ли вернуть гнома в рабочее состояние, если удастся собрать все запчасти.", rare = true, fragments = 100, sockets = 3, texture = "Interface\\Archeology\\ArchRare-ClockworkGnome" },
	[189] = { branch = 1, name = "Чаша Горных королей", description = "Вы моментально определяете, что этот питьевой сосуд служит не только – и не столько – для утоления жажды (хотя и в этом дворфы кому угодно дадут фору). Фрагмент рун, который вам удается распознать, намекает на ритуальное назначение чаши.", rare = true, fragments = 100, sockets = 3, texture = "Interface\\Archeology\\ArchRare-ChaliceMountainKings" },
	[191] = { branch = 8, name = "Зуб с золотой пломбой", description = "Полагают, что племя Зандалар было первым племенем троллей и что все остальные тролли произошли от него. Зандалар считались высшей кастой жрецов. Тролли из этого племени без устали работали над тем, чтобы сохранить традиции троллей и их социальный уклад. Из многочисленных племен, отколовшихся ранее от Зандалар, двумя самыми могущественными являются Гурубаши и Амани.", rare = false, fragments = 35, sockets = 1, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[193] = { branch = 8, name = "Жертвенный нож Драккари", description = "Полагают, что племя Зандалар было первым племенем троллей и что все остальные тролли произошли от него. Зандалар считались высшей кастой жрецов. Тролли из этого племени без устали работали над тем, чтобы сохранить традиции троллей и их социальный уклад. Из многочисленных племен, отколовшихся ранее от Зандалар, двумя самыми могущественными являются Гурубаши и Амани.", rare = false, fragments = 35, sockets = 1, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[195] = { branch = 8, name = "Зин-Рок, Разрушитель Миров", description = "Вы, очевидно, наткнулись на фрагмент очень мощного оружия троллей. Быть может, удастся его воссоздать?", rare = true, fragments = 150, sockets = 3, texture = "Interface\\Archeology\\ArchRare-ZinRokhDestroyer" },
	[197] = { branch = 4, name = "Нитка мелкого розового жемчуга", description = "Калдорай – одна из древнейших рас Азерота. Самый мрачный момент в их истории пришелся на период, когда кель'дорай – Высокорожденные, высшая каста эльфов – высвободили опасную магию. Она привлекла в мир Пылающий Легион, чей приход повлек за собой бесчисленные жертвы.", rare = false, fragments = 35, sockets = 1, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[199] = { branch = 4, name = "Сундук с маленькими стеклянными фигурками животных", description = "Калдорай – одна из древнейших рас Азерота. Самый мрачный момент в их истории пришелся на период, когда кель'дорай – Высокорожденные, высшая каста эльфов – высвободили опасную магию. Она привлекла в мир Пылающий Легион, чей приход повлек за собой бесчисленные жертвы.", rare = false, fragments = 34, sockets = 1, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[201] = { branch = 4, name = "Треснувший хрустальный флакон", description = "Калдорай – одна из древнейших рас Азерота. Самый мрачный момент в их истории пришелся на период, когда кель'дорай – Высокорожденные, высшая каста эльфов – высвободили опасную магию. Она привлекла в мир Пылающий Легион, чей приход повлек за собой бесчисленные жертвы.", rare = false, fragments = 35, sockets = 1, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[203] = { branch = 4, name = "Скипетр Ксавия", description = "Калдорай – одна из древнейших рас Азерота. Самый мрачный момент в их истории пришелся на период, когда кель'дорай – Высокорожденные, высшая каста эльфов – высвободили опасную магию. Она привлекла в мир Пылающий Легион, чей приход повлек за собой бесчисленные жертвы.", rare = false, fragments = 35, sockets = 1, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[205] = { branch = 4, name = "Калдорайская \"песня ветра\"", description = "Это необычные бронзовые трубки. Вы чувствуете, что они все еще хранят толику магии. Если их положить рядом, даже в сумке, обломки трубок словно сами притягиваются друг к другу.", rare = true, fragments = 98, sockets = 3, texture = "Interface\\Archeology\\ArchRare-KaldoreiWindChimes" },
	[207] = { branch = 4, name = "Пеньюар королевы Азшары", description = "Похоже, молва о манере Высокорожденных безвкусно одеваться была правдива.", rare = true, fragments = 100, sockets = 3, texture = "Interface\\Archeology\\ArchRare-QueenAzsharaGown" },
	[209] = { branch = 3, name = "Оперенная лапка ящера", description = "Ископаемые – это сохранившиеся останки животных и растений древних эпох. Как правило, живые ткани замещаются минералами, которые сохраняют строение некогда живого организма.", rare = false, fragments = 33, sockets = 0, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[211] = { branch = 3, name = "Хищная древняя рыба", description = "Ископаемые – это сохранившиеся останки животных и растений древних эпох. Как правило, живые ткани замещаются минералами, которые сохраняют строение некогда живого организма.", rare = false, fragments = 35, sockets = 0, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[213] = { branch = 3, name = "Ископаемый ящер", description = "Есть что-то подозрительное в скелете этого ящера. Стоит вам отвести взгляд, как кажется, что кости начинают едва заметно шевелиться.", rare = true, fragments = 100, sockets = 0, texture = "Interface\\Archeology\\ArchRare-DinosaurSkeleton" },
	[215] = { branch = 6, name = "Маленький бронзовый скорпион", description = "Изначально орки Азерота обитали в мире Дренор, откуда родом все их древнейшие артефакты. Ранее это был довольно мирный народ, но под влиянием Пылающего Легиона он стал оплотом откровенного варварства. В Азерот орки попали через Темный портал. Они успели отвоевать две войны против Альянса; третья, вероятно, не за горами.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[217] = { branch = 6, name = "Молот каменного стража Мур'ога", description = "Изначально орки Азерота обитали в мире Дренор, откуда родом все их древнейшие артефакты. Ранее это был довольно мирный народ, но под влиянием Пылающего Легиона он стал оплотом откровенного варварства. В Азерот орки попали через Темный портал. Они успели отвоевать две войны против Альянса; третья, вероятно, не за горами.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[219] = { branch = 6, name = "Серый огарок свечи", description = "Изначально орки Азерота обитали в мире Дренор, откуда родом все их древнейшие артефакты. Ранее это был довольно мирный народ, но под влиянием Пылающего Легиона он стал оплотом откровенного варварства. В Азерот орки попали через Темный портал. Они успели отвоевать две войны против Альянса; третья, вероятно, не за горами.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[221] = { branch = 6, name = "Ржавый мясницкий нож", description = "Изначально орки Азерота обитали в мире Дренор, откуда родом все их древнейшие артефакты. Ранее это был довольно мирный народ, но под влиянием Пылающего Легиона он стал оплотом откровенного варварства. В Азерот орки попали через Темный портал. Они успели отвоевать две войны против Альянса; третья, вероятно, не за горами.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[223] = { branch = 6, name = "Скипетр Некроса Дробителя Черепов", description = "Изначально орки Азерота обитали в мире Дренор, откуда родом все их древнейшие артефакты. Ранее это был довольно мирный народ, но под влиянием Пылающего Легиона он стал оплотом откровенного варварства. В Азерот орки попали через Темный портал. Они успели отвоевать две войны против Альянса; третья, вероятно, не за горами.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[225] = { branch = 6, name = "Фигурка свирепого волка", description = "Изначально орки Азерота обитали в мире Дренор, откуда родом все их древнейшие артефакты. Ранее это был довольно мирный народ, но под влиянием Пылающего Легиона он стал оплотом откровенного варварства. В Азерот орки попали через Темный портал. Они успели отвоевать две войны против Альянса; третья, вероятно, не за горами.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[231] = { branch = 6, name = "Кубок из черепа", description = "Изначально орки Азерота обитали в мире Дренор, откуда родом все их древнейшие артефакты. Ранее это был довольно мирный народ, но под влиянием Пылающего Легиона он стал оплотом откровенного варварства. В Азерот орки попали через Темный портал. Они успели отвоевать две войны против Альянса; третья, вероятно, не за горами.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[233] = { branch = 6, name = "Глазурованная глиняная плитка", description = "Изначально орки Азерота обитали в мире Дренор, откуда родом все их древнейшие артефакты. Ранее это был довольно мирный народ, но под влиянием Пылающего Легиона он стал оплотом откровенного варварства. В Азерот орки попали через Темный портал. Они успели отвоевать две войны против Альянса; третья, вероятно, не за горами.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[235] = { branch = 6, name = "Демонический бич", description = "Изначально орки Азерота обитали в мире Дренор, откуда родом все их древнейшие артефакты. Ранее это был довольно мирный народ, но под влиянием Пылающего Легиона он стал оплотом откровенного варварства. В Азерот орки попали через Темный портал. Они успели отвоевать две войны против Альянса; третья, вероятно, не за горами.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[237] = { branch = 6, name = "Головной убор Первого шамана", description = "Ваша находка – лохмотья головного убора, изготовленного из волчьей головы. Несмотря на внешнюю аляповатость вещи, вы чувствуете, что это древний, значимый и могущественный артефакт.", rare = true, fragments = 130, sockets = 3, texture = "Interface\\Archeology\\ArchRare-AncientShamanHeaddress" },
	[239] = { branch = 2, name = "Ножной браслет с золотыми колокольчиками", description = "Дренеи некогда были эредарами, которые бежали от Пылающего Легиона и обосновались в мире Дренор, где столкнулись с орками. С приходом эльфов крови многие дренеи вновь были вынуждены уйти, на этот раз в Азерот, где они присоединились к Альянсу.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[241] = { branch = 2, name = "Резная арфа из экзотических пород дерева", description = "Дренеи некогда были эредарами, которые бежали от Пылающего Легиона и обосновались в мире Дренор, где столкнулись с орками. С приходом эльфов крови многие дренеи вновь были вынуждены уйти, на этот раз в Азерот, где они присоединились к Альянсу.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[243] = { branch = 2, name = "Странное серебристое пресс-папье", description = "Дренеи некогда были эредарами, которые бежали от Пылающего Легиона и обосновались в мире Дренор, где столкнулись с орками. С приходом эльфов крови многие дренеи вновь были вынуждены уйти, на этот раз в Азерот, где они присоединились к Альянсу.", rare = false, fragments = 46, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[245] = { branch = 2, name = "Натрезимский скипетр", description = "Дренеи некогда были эредарами, которые бежали от Пылающего Легиона и обосновались в мире Дренор, где столкнулись с орками. С приходом эльфов крови многие дренеи вновь были вынуждены уйти, на этот раз в Азерот, где они присоединились к Альянсу.", rare = false, fragments = 46, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[250] = { branch = 2, name = "Расписные ножны", description = "Дренеи некогда были эредарами, которые бежали от Пылающего Легиона и обосновались в мире Дренор, где столкнулись с орками. С приходом эльфов крови многие дренеи вновь были вынуждены уйти, на этот раз в Азерот, где они присоединились к Альянсу.", rare = false, fragments = 46, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[252] = { branch = 2, name = "Изящный канделябр из кристаллов", description = "Дренеи некогда были эредарами, которые бежали от Пылающего Легиона и обосновались в мире Дренор, где столкнулись с орками. С приходом эльфов крови многие дренеи вновь были вынуждены уйти, на этот раз в Азерот, где они присоединились к Альянсу.", rare = false, fragments = 44, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[254] = { branch = 2, name = "Величавый портрет", description = "Дренеи некогда были эредарами, которые бежали от Пылающего Легиона и обосновались в мире Дренор, где столкнулись с орками. С приходом эльфов крови многие дренеи вновь были вынуждены уйти, на этот раз в Азерот, где они присоединились к Альянсу.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[256] = { branch = 2, name = "Свидетельство визита Наару", description = "Наару – богоподобная раса существ из чистой энергии, истовых приверженцев Света. Впервые наару явились дренеям, когда пророк Велен взмолился о спасении от Пылающего Легиона. Наару вняли его зову и помогли Велену и его народу спастись. В переводе \"дренеи\" обозначает \"изгнанники\".", rare = true, fragments = 124, sockets = 3, texture = "Interface\\Archeology\\ArchRare-DraeneiRelic" },
	[258] = { branch = 2, name = "Последняя реликвия Аргуса", description = "Обыкновенный кристалл дренеев, возраст которого насчитывает тысячелетия. Вы вполне уверены, что он не из этого мира.", rare = true, fragments = 130, sockets = 3, texture = "Interface\\Archeology\\ArchRare-DraeneiRelic" },
	[260] = { branch = 2, name = "Стрекало для элекков", description = "Дренеи некогда были эредарами, которые бежали от Пылающего Легиона и обосновались в мире Дренор, где столкнулись с орками. С приходом эльфов крови многие дренеи вновь были вынуждены уйти, на этот раз в Азерот, где они присоединились к Альянсу.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[262] = { branch = 27, name = "Замысловатый ключ от сундука с сокровищами", description = "Врайкулы – раса воинов-исполинов, населяющая Ревущий фьорд в Нордсколе. Врайкулы находятся в тесной связи с морем и обитающими в окрестностях протодраконами. Многие врайкулы присоединились к бесчисленному войску Короля-лича.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[264] = { branch = 27, name = "Ниффлварский бородовидный топор", description = "Лезвие этого топора асимметрично, с длинной кромкой. Вам кажется, что если восстановить оружие, магические свойства к нему вернутся.", rare = true, fragments = 130, sockets = 3, texture = "Interface\\Archeology\\Arch-TempRareSketch" },
	[266] = { branch = 27, name = "Скрамсакс", description = "Врайкулы – раса воинов-исполинов, населяющая Ревущий фьорд в Нордсколе. Врайкулы находятся в тесной связи с морем и обитающими в окрестностях протодраконами. Многие врайкулы присоединились к бесчисленному войску Короля-лича.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[268] = { branch = 27, name = "Огниво", description = "Врайкулы – раса воинов-исполинов, населяющая Ревущий фьорд в Нордсколе. Врайкулы находятся в тесной связи с морем и обитающими в окрестностях протодраконами. Многие врайкулы присоединились к бесчисленному войску Короля-лича.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[270] = { branch = 27, name = "Украшенная клыками булавка для плаща", description = "Врайкулы – раса воинов-исполинов, населяющая Ревущий фьорд в Нордсколе. Врайкулы находятся в тесной связи с морем и обитающими в окрестностях протодраконами. Многие врайкулы присоединились к бесчисленному войску Короля-лича.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[273] = { branch = 27, name = "Ожерелье острых шипов", description = "Врайкулы – раса воинов-исполинов, населяющая Ревущий фьорд в Нордсколе. Врайкулы находятся в тесной связи с морем и обитающими в окрестностях протодраконами. Многие врайкулы присоединились к бесчисленному войску Короля-лича.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[275] = { branch = 3, name = "Скелет протодракона", description = "Ископаемые – это сохранившиеся останки животных и растений древних эпох. Как правило, живые ткани замещаются минералами, которые сохраняют строение некогда живого организма.", rare = false, fragments = 45, sockets = 0, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[277] = { branch = 3, name = "Отпечаток щупальца кракена", description = "Ископаемые – это сохранившиеся останки животных и растений древних эпох. Как правило, живые ткани замещаются минералами, которые сохраняют строение некогда живого организма.", rare = false, fragments = 45, sockets = 0, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[279] = { branch = 5, name = "Паучьи солнечные часы", description = "Нерубы – потомки древней расы акир, примерно половина которой переселилась на дальний север после затяжной войны с троллями. Там, в недрах Нордскола, они построили громадный город-государство – легендарный Азжол-Неруб. С приходом Короля-лича яростным нерубам пришлось нелегко – многие арахниды были обращены в нежить, остальные же скрылись в недрах земли.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[283] = { branch = 5, name = "Скипетр Незар'азрет", description = "Нерубы – потомки древней расы акир, примерно половина которой переселилась на дальний север после затяжной войны с троллями. Там, в недрах Нордскола, они построили громадный город-государство – легендарный Азжол-Неруб. С приходом Короля-лича яростным нерубам пришлось нелегко – многие арахниды были обращены в нежить, остальные же скрылись в недрах земли.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[285] = { branch = 5, name = "Инвазированное рубиновое кольцо", description = "Нерубы – потомки древней расы акир, примерно половина которой переселилась на дальний север после затяжной войны с троллями. Там, в недрах Нордскола, они построили громадный город-государство – легендарный Азжол-Неруб. С приходом Короля-лича яростным нерубам пришлось нелегко – многие арахниды были обращены в нежить, остальные же скрылись в недрах земли.", rare = false, fragments = 45, sockets = 3, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[287] = { branch = 5, name = "Ларец тяжелого сердца", description = "Нерубы – потомки древней расы акир, примерно половина которой переселилась на дальний север после затяжной войны с троллями. Там, в недрах Нордскола, они построили громадный город-государство – легендарный Азжол-Неруб. С приходом Короля-лича яростным нерубам пришлось нелегко – многие арахниды были обращены в нежить, остальные же скрылись в недрах земли.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[289] = { branch = 5, name = "Лепнина в виде шестипалого существа", description = "Нерубы – потомки древней расы акир, примерно половина которой переселилась на дальний север после затяжной войны с троллями. Там, в недрах Нордскола, они построили громадный город-государство – легендарный Азжол-Неруб. С приходом Короля-лича яростным нерубам пришлось нелегко – многие арахниды были обращены в нежить, остальные же скрылись в недрах земли.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[291] = { branch = 5, name = "Бутылка с кровью йормунгара", description = "Нерубы – потомки древней расы акир, примерно половина которой переселилась на дальний север после затяжной войны с троллями. Там, в недрах Нордскола, они построили громадный город-государство – легендарный Азжол-Неруб. С приходом Короля-лича яростным нерубам пришлось нелегко – многие арахниды были обращены в нежить, остальные же скрылись в недрах земли.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[293] = { branch = 5, name = "Послание визиря", description = "Нерубы – потомки древней расы акир, примерно половина которой переселилась на дальний север после затяжной войны с троллями. Там, в недрах Нордскола, они построили громадный город-государство – легендарный Азжол-Неруб. С приходом Короля-лича яростным нерубам пришлось нелегко – многие арахниды были обращены в нежить, остальные же скрылись в недрах земли.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[295] = { branch = 5, name = "Благословение древнего бога", description = "Вы обнаружили предмет, исполненный зла. Ваша голова раскалывается от боли при взгляде даже на фрагменты этого артефакта. Вы опасаетесь, что, собери вы его целиком, он сведет вас с ума.", rare = true, fragments = 140, sockets = 3, texture = "Interface\\Archeology\\ArchRare-OldGodTrinket" },
	[297] = { branch = 5, name = "Головоломка Йогг-Сарона", description = "Части этого артефакта издают бессмысленный шепот, который вливается в сводящий с ума шелестящий хор, становящийся все невыносимее с каждым новым найденным фрагментом. Вы надеетесь лишь на то, что сумеете удержать ситуацию под контролем.", rare = true, fragments = 140, sockets = 3, texture = "Interface\\Archeology\\ArchRare-CthunsPuzzleBox" },
	[301] = { branch = 1, name = "Серебряный кривой кинжал Корла", description = "Дворфы Стальгорна некогда происходили из трех кланов: Бронзобородов, Громового Молота и Черного Железа. После гражданской войны Бронзобороды остались править в Стальгорне, клан Громового Молота отступил во Внутренние Земли и на Сумеречное нагорье. Дворфы же Черного Железа обосновались между Красногорьем и Пылающими степями, под сенью Черной горы.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[303] = { branch = 1, name = "Боевой молот Пылающего Ока", description = "Дворфы Стальгорна некогда происходили из трех кланов: Бронзобородов, Громового Молота и Черного Железа. После гражданской войны Бронзобороды остались править в Стальгорне, клан Громового Молота отступил во Внутренние Земли и на Сумеречное нагорье. Дворфы же Черного Железа обосновались между Красногорьем и Пылающими степями, под сенью Черной горы.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[305] = { branch = 1, name = "Шипованные рукавицы Ярости Горна", description = "Дворфы Стальгорна некогда происходили из трех кланов: Бронзобородов, Громового Молота и Черного Железа. После гражданской войны Бронзобороды остались править в Стальгорне, клан Громового Молота отступил во Внутренние Земли и на Сумеречное нагорье. Дворфы же Черного Железа обосновались между Красногорьем и Пылающими степями, под сенью Черной горы.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[307] = { branch = 1, name = "Слово императрицы Зои", description = "Дворфы Стальгорна некогда происходили из трех кланов: Бронзобородов, Громового Молота и Черного Железа. После гражданской войны Бронзобороды остались править в Стальгорне, клан Громового Молота отступил во Внутренние Земли и на Сумеречное нагорье. Дворфы же Черного Железа обосновались между Красногорьем и Пылающими степями, под сенью Черной горы.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[309] = { branch = 1, name = "Скипетр Бронзобородов", description = "Дворфы Стальгорна некогда происходили из трех кланов: Бронзобородов, Громового Молота и Черного Железа. После гражданской войны Бронзобороды остались править в Стальгорне, клан Громового Молота отступил во Внутренние Земли и на Сумеречное нагорье. Дворфы же Черного Железа обосновались между Красногорьем и Пылающими степями, под сенью Черной горы.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[313] = { branch = 1, name = "Дочь трактирщика", description = "Этот небольшой камень напоминает камень возвращения. Он теплый на ощупь и будто бы едва слышно хихикает в самые неподходящие моменты.", rare = true, fragments = 150, sockets = 3, texture = "Interface\\Archeology\\ArchRare-TheInnKeepersDaughter" },
	[315] = { branch = 1, name = "Посох тана-чародея Тауриссана", description = "Обломки этого посоха по сей день потрескивают от переполняющей их энергии. Посох, ко всему прочему, сильно пострадал от огня.", rare = true, fragments = 150, sockets = 3, texture = "Interface\\Archeology\\ArchRare-StaffofSorcererThanThaurissan" },
	[317] = { branch = 4, name = "Любимая кукла Тиранды", description = "Это обыкновенная кукла ночных эльфов. Ручки и ножки у нее фарфоровые, выкрашенные ныне облупившейся фиолетовой краской. Одежка изящная, но потрепанная. А самое примечательное в кукле – ее длинные локоны. Возможно, они сделаны из настоящих эльфийских волос.", rare = true, fragments = 150, sockets = 3, texture = "Interface\\Archeology\\ArchRare-TyrandesFavoriteDoll" },
	[319] = { branch = 4, name = "Кости перерождения", description = "Эта находка представляет собой необычное сочетание человеческих рук и змеиного хвоста. Очевидно, кости принадлежали наге. Однако любопытнее другое: скелет застыл в постановочной позе, словно некогда выставлялся в музее.", rare = true, fragments = 150, sockets = 3, texture = "Interface\\Archeology\\ArchRare-BonesOfTransformation" },
	[323] = { branch = 4, name = "Ожерелье сотни магов", description = "Калдорай – одна из древнейших рас Азерота. Самый мрачный момент в их истории пришелся на период, когда кель'дорай – Высокорожденные, высшая каста эльфов – высвободили опасную магию. Она привлекла в мир Пылающий Легион, чей приход повлек за собой бесчисленные жертвы.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[325] = { branch = 4, name = "Серебряный футляр для свитков", description = "Калдорай – одна из древнейших рас Азерота. Самый мрачный момент в их истории пришелся на период, когда кель'дорай – Высокорожденные, высшая каста эльфов – высвободили опасную магию. Она привлекла в мир Пылающий Легион, чей приход повлек за собой бесчисленные жертвы.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[327] = { branch = 4, name = "Серповидный клинок теней", description = "Калдорай – одна из древнейших рас Азерота. Самый мрачный момент в их истории пришелся на период, когда кель'дорай – Высокорожденные, высшая каста эльфов – высвободили опасную магию. Она привлекла в мир Пылающий Легион, чей приход повлек за собой бесчисленные жертвы.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[329] = { branch = 4, name = "Амулет-огонек", description = "Это красивый амулет с большим каплевидным изумрудом, обрамленным узорами из светлого золота. В самой сердцевине камня виднеется сияющая сфера с едва различимым изображением лица ночного эльфа. Сфера словно движется в изумруде – не находится на одном месте, а порхает, как мотылек.", rare = true, fragments = 150, sockets = 3, texture = "Interface\\Archeology\\ArchRare-WispAmulet" },
	[331] = { branch = 7, name = "Песочный замок", description = "Тол'виры некогда были каменными изваяниями, поставленными титанами на защиту тайн Ульдума. Нижняя часть тела и голова у них кошачья, а торс – человеческий. Как и многие другие детища титанов, они подверглись проклятию плоти. Ныне осталось три племени тол'виров – Рамкахен, Орсис (почти полностью истреблено) и Неферсет. Последние заключили союз со Смертокрылом в обмен на обещание вновь обратить их плоть в камень.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[333] = { branch = 7, name = "Статуя кошки с глазами-изумрудами", description = "Тол'виры некогда были каменными изваяниями, поставленными титанами на защиту тайн Ульдума. Нижняя часть тела и голова у них кошачья, а торс – человеческий. Как и многие другие детища титанов, они подверглись проклятию плоти. Ныне осталось три племени тол'виров – Рамкахен, Орсис (почти полностью истреблено) и Неферсет. Последние заключили союз со Смертокрылом в обмен на обещание вновь обратить их плоть в камень.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[335] = { branch = 7, name = "Ожерелье со скарабеями из мыльного камня", description = "Тол'виры некогда были каменными изваяниями, поставленными титанами на защиту тайн Ульдума. Нижняя часть тела и голова у них кошачья, а торс – человеческий. Как и многие другие детища титанов, они подверглись проклятию плоти. Ныне осталось три племени тол'виров – Рамкахен, Орсис (почти полностью истреблено) и Неферсет. Последние заключили союз со Смертокрылом в обмен на обещание вновь обратить их плоть в камень.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[339] = { branch = 7, name = "Маленькая оазисная мозаика", description = "Тол'виры некогда были каменными изваяниями, поставленными титанами на защиту тайн Ульдума. Нижняя часть тела и голова у них кошачья, а торс – человеческий. Как и многие другие детища титанов, они подверглись проклятию плоти. Ныне осталось три племени тол'виров – Рамкахен, Орсис (почти полностью истреблено) и Неферсет. Последние заключили союз со Смертокрылом в обмен на обещание вновь обратить их плоть в камень.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[341] = { branch = 7, name = "Гравированная рукоять ятагана", description = "Тол'виры некогда были каменными изваяниями, поставленными титанами на защиту тайн Ульдума. Нижняя часть тела и голова у них кошачья, а торс – человеческий. Как и многие другие детища титанов, они подверглись проклятию плоти. Ныне осталось три племени тол'виров – Рамкахен, Орсис (почти полностью истреблено) и Неферсет. Последние заключили союз со Смертокрылом в обмен на обещание вновь обратить их плоть в камень.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[343] = { branch = 7, name = "Канопа", description = "Тол'виры некогда были каменными изваяниями, поставленными титанами на защиту тайн Ульдума. Нижняя часть тела и голова у них кошачья, а торс – человеческий. Как и многие другие детища титанов, они подверглись проклятию плоти. Ныне осталось три племени тол'виров – Рамкахен, Орсис (почти полностью истреблено) и Неферсет. Последние заключили союз со Смертокрылом в обмен на обещание вновь обратить их плоть в камень.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[345] = { branch = 7, name = "Эскиз Дворца Пустыни", description = "Тол'виры некогда были каменными изваяниями, поставленными титанами на защиту тайн Ульдума. Нижняя часть тела и голова у них кошачья, а торс – человеческий. Как и многие другие детища титанов, они подверглись проклятию плоти. Ныне осталось три племени тол'виров – Рамкахен, Орсис (почти полностью истреблено) и Неферсет. Последние заключили союз со Смертокрылом в обмен на обещание вновь обратить их плоть в камень.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[347] = { branch = 1, name = "Трубка Франклорна Искусника", description = "Дворфы Стальгорна некогда происходили из трех кланов: Бронзобородов, Громового Молота и Черного Железа. После гражданской войны Бронзобороды остались править в Стальгорне, клан Громового Молота отступил во Внутренние Земли и на Сумеречное нагорье. Дворфы же Черного Железа обосновались между Красногорьем и Пылающими степями, под сенью Черной горы.", rare = false, fragments = 45, sockets = 2, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[349] = { branch = 7, name = "Мумифицированная обезьянья лапка", description = "Это не что иное, как конечность мелкого примата. Рассмотрев лапку более пристально, вы отмечаете, что сотни лет в песках Ульдума полностью иссушили ее. И все же вы уверены, что это необыкновенная находка.", rare = true, fragments = 150, sockets = 3, texture = "Interface\\Archeology\\ArchRare-ShriveledMonkeyPaw" },
	[351] = { branch = 7, name = "Посох Аммунаэ", description = "Перед вами длинный посох с золотым набалдашником. В середину набалдашника вставлен зеленый камень неизвестной породы, который пропускает свет. На ощупь посох теплый, а если оставить его в окружении растений, они поворачиваются к нему, словно к солнцу.", rare = true, fragments = 150, sockets = 3, texture = "Interface\\Archeology\\ArchRare-StaffofAmmunrae" },
	[353] = { branch = 7, name = "Подвеска нашествия скарабеев", description = "Это массивное ожерелье напоминает скорее часть доспеха, разве что состоит из маленьких каменных и бронзовых скарабеев вместо кольчужных звеньев. Самый крупный скарабей высечен из лазурита и обрамлен золотом.", rare = true, fragments = 150, sockets = 3, texture = "Interface\\Archeology\\ArchRare-PendantoftheAqir" },
	[355] = { branch = 7, name = "Скипетр Аз'Акир", description = "Короткий скипетр увенчан аметистом с золотыми зубцами. Вы можете с уверенностью сказать, что посох принадлежит к киражской, а не тол'вирской культуре. Возможно, ввиду относительной близости храма Ан'Киража артефакт сумел попасть в Ульдум несмотря на барьер.", rare = true, fragments = 150, sockets = 3, texture = "Interface\\Archeology\\ArchRare-ScepterofAzAqir" },
	[357] = { branch = 7, name = "Ятаган сирокко", description = "Этот ятаган выкован из бронзы, но и золота на инкрустацию не пожалели. Теплый ветерок так и льнет к оружию. Клинок сильно изогнут на манер серпа – тол'виры называют такие мечи \"хопеш\".", rare = true, fragments = 150, sockets = 3, texture = "Interface\\Archeology\\ArchRare-ScimitaroftheSirocco" },
	[359] = { branch = 7, name = "Кольцо маленького императора", description = "Это золотое кольцо со скарабеем из полированной бирюзы. Колечко само по себе довольно маленькое: оно с трудом налезает на ваш палец.", rare = true, fragments = 150, sockets = 3, texture = "Interface\\Archeology\\ArchRare-RingoftheBoyEmperor" },
	[371] = { branch = 1, name = "Дворфийские детские носочки", description = "Дворфы Стальгорна некогда происходили из трех кланов: Бронзобородов, Громового Молота и Черного Железа. После гражданской войны Бронзобороды остались править в Стальгорне, клан Громового Молота отступил во Внутренние Земли и на Сумеречное нагорье. Дворфы же Черного Железа обосновались между Красногорьем и Пылающими степями, под сенью Черной горы.", rare = false, fragments = 30, sockets = 0, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[372] = { branch = 4, name = "Ожерелье с подвеской Элуны", description = "Калдорай – одна из древнейших рас Азерота. Самый мрачный момент в их истории пришелся на период, когда кель'дорай – Высокорожденные, высшая каста эльфов – высвободили опасную магию. Она привлекла в мир Пылающий Легион, чей приход повлек за собой бесчисленные жертвы.", rare = false, fragments = 30, sockets = 0, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[374] = { branch = 3, name = "Осколок окаменевшего дерева", description = "Ископаемые – это сохранившиеся останки животных и растений древних эпох. Как правило, живые ткани замещаются минералами, которые сохраняют строение некогда живого организма.", rare = false, fragments = 30, sockets = 0, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[378] = { branch = 3, name = "Странный бархатистый червь", description = "Ископаемые – это сохранившиеся останки животных и растений древних эпох. Как правило, живые ткани замещаются минералами, которые сохраняют строение некогда живого организма.", rare = false, fragments = 35, sockets = 0, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[380] = { branch = 8, name = "Изысканный обеденный прибор Кровавого Скальпа", description = "Полагают, что племя Зандалар было первым племенем троллей и что все остальные тролли произошли от него. Зандалар считались высшей кастой жрецов. Тролли из этого племени без устали работали над тем, чтобы сохранить традиции троллей и их социальный уклад. Из многочисленных племен, отколовшихся ранее от Зандалар, двумя самыми могущественными являются Гурубаши и Амани.", rare = false, fragments = 32, sockets = 0, texture = "Interface\\Archeology\\Arch-TempLogoBig" },
	[628] = { branch = 3, name = "Панцирь вымершей черепахи", description = "Это кусок невероятно крепкого панциря. Возможно, если вы найдете все фрагменты, они соединятся в прочную броню.", rare = true, fragments = 150, sockets = 0, texture = "Interface\\Archeology\\ArchRare-TurtleShield" },
	[633] = { branch = 8, name = "Заколдованный боевой барабан", description = "Богато украшенный тролльский боевой барабан, выглядит очень древним. На него натянута шкура необычного цвета. Кажется, она покрыта татуировками, а не просто орнаментом.", rare = true, fragments = 100, sockets = 3, texture = "Interface\\Archeology\\ArchRare-TrollDrum" },
	[635] = { branch = 3, name = "Древний янтарь", description = "Очень крупный кусок окаменевшей смолы, в котором, кажется, застыла человекоподобная фигурка.", rare = true, fragments = 100, sockets = 0, texture = "Interface\\Archeology\\ArchRare-AmberFly" },
	[637] = { branch = 27, name = "Врайкульский рог для вина", description = "Большой, крепкий рог, украшенный рунами и серебром.", rare = true, fragments = 100, sockets = 3, texture = "Interface\\Archeology\\ArchRare-VrykulDrinkingHorn" },
	[639] = { branch = 3, name = "Птенец терродактиля", description = "Неужели в этом окаменелом яйце еще теплится жизнь?..", rare = true, fragments = 120, sockets = 0, texture = "Interface\\Archeology\\ArchRare-BabyPterrodax" },
	[641] = { branch = 8, name = "Фигурка вуду", description = "Небольшая причудливая фигурка, изготовленная троллем.", rare = true, fragments = 100, sockets = 3, texture = "Interface\\Archeology\\ArchRare-TrollGolem" },
};
